satz = "Wenn Robben hinter Robben robben, robben Robben Robben nach."

def zaehler(text, substring):
    anzahl = text.count(substring)
    return anzahl

def ersetzer(text, alt, neu):
    return text.replace(alt, neu)

print(zaehler(satz, "b"))                                    # 12
print(zaehler(ersetzer(satz, "Robben", "Seehunde"), "Robben"))  # 0

