exercises.solution:
def euro_in_cent(text):
    teile = text.replace(",", ".").split(".")
    return int(teile[0]) * 100 + int(teile[1])

def spielstand(protokoll):
    punkte_spieler1 = 0
    punkte_spieler2 = 0
    for eintrag in protokoll.split(","):
        teile = eintrag.split(":")
        if teile[0] == "S1":
            punkte_spieler1 = punkte_spieler1 + int(teile[1])
        else:
            punkte_spieler2 = punkte_spieler2 + int(teile[1])
    return "Spieler 1: {} Punkte, Spieler 2: {} Punkte".format(punkte_spieler1, punkte_spieler2)
